pub async fn fetch_all(ids: Vec<JobId>) -> Result<Vec<Output>, FetchError> {
    let mut handles = Vec::new();
    for id in ids {
        handles.push(tokio::spawn(async move { fetch(id).await }));
    }

    let mut outputs = Vec::new();
    for handle in handles {
        outputs.push(handle.await.unwrap()?);
    }
    Ok(outputs)
}
```

