```rust
pub fn parse_discounts(lines: &[String]) -> Result<Vec<(String, u8, bool, bool)>, String> {
    let mut out = Vec::new();
    for line in lines {
        let fields: Vec<_> = line.split(',').collect();
        let percent: u8 = fields[1].parse().map_err(|_| "bad percent".to_string())?;
        let stackable = fields[2] == "stack";
        let exclusive = fields[2] == "exclusive";
        out.push((fields[0].to_string(), percent, stackable, exclusive));
    }
    Ok(out)
}
```

